export function unifiedReviewLabel(item){
  const subject=String(item?.subject||'').trim(),l=String(item?.label||'').trim();
  if(!subject||!l)return l||'Revisão';
  const escaped=subject.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  return l.replace(new RegExp(`^${escaped}\\s*[·•—-]\\s*`,'i'),'').trim()||'Revisão';
}
